from collections import deque

def bfs_at_depth(graph, start, target_depth):
    """Return nodes at exactly target_depth from start node (not including start)"""
    if target_depth <= 0:
        return []

    visited = {start: 0}  # node -> depth
    queue = deque([start])
    result = []

    while queue:
        current = queue.popleft()
        current_depth = visited[current]

        # If we've gone past target depth, stop
        if current_depth >= target_depth:
            continue

        for neighbor in graph.get(current, []):
            if neighbor not in visited:
                visited[neighbor] = current_depth + 1
                if current_depth + 1 == target_depth:
                    result.append(neighbor)
                queue.append(neighbor)

    return result

# BFS level by level to trace
def bfs_trace(graph, start, max_depth):
    """Trace BFS level by level"""
    levels = {0: [start]}
    visited = {start}

    for depth in range(max_depth):
        next_level = []
        for node in levels[depth]:
            for neighbor in graph.get(node, []):
                if neighbor not in visited:
                    visited.add(neighbor)
                    next_level.append(neighbor)
        levels[depth + 1] = next_level
        print(f"Depth {depth + 1}: {next_level}")

    return levels

